:root {
  --brand-primary: #1a3a5c;
  --brand-accent: #e8a020;
  --brand-light: #e8f0fa;
  --card-bg: #ffffff;
  --header-bg: #1a3a5c;
  --footer-bg: #f0f4fa;
  --text-primary: #1a2a3a;
  --text-secondary: #5a6a7a;
  --text-light: #ffffff;
  --zone-a-bg: #1a3a5c;
  --zone-b-bg: #2e7d52;
  --zone-c-bg: #7b3fa0;
  --zone-text: #ffffff;
  --avatar-bg: #e8a020;
  --avatar-text: #1a3a5c;
  --border-color: #d0dcea;
  --bar-color: #1a2a3a;
  --barcode-text: #8a9aaa;
}

.pass-card {
  width: 480px;
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid var(--border-color);
  background: var(--card-bg);
  margin: 20px auto;
}

.pass-header {
  background: var(--header-bg);
  padding: 14px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.transit-logo {
  display: flex;
  align-items: center;
  gap: 10px;
}

.logo-icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: var(--brand-accent);
  color: var(--avatar-text);
  font-size: 20px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-text {
  display: flex;
  flex-direction: column;
}

.logo-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-light);
  line-height: 1.2;
}

.logo-sub {
  font-size: 10px;
  color: var(--brand-accent);
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: 0.04em;
}

.pass-type {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--brand-accent);
  border: 1.5px solid var(--brand-accent);
  border-radius: 6px;
  padding: 4px 10px;
}

.pass-body {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 16px 20px;
  background: var(--card-bg);
  border-bottom: 1px solid var(--border-color);
}

.rider-section {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  flex: 1;
}

.rider-avatar {
  width: 52px;
  height: 52px;
  border-radius: 12px;
  background: var(--avatar-bg);
  color: var(--avatar-text);
  font-size: 18px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.rider-info {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.rider-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.rider-id {
  font-size: 11px;
  color: var(--text-secondary);
  font-weight: 500;
}

.zone-badges {
  display: flex;
  gap: 5px;
  margin-top: 4px;
}

.zone {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 20px;
  color: var(--zone-text);
  letter-spacing: 0.04em;
}

.zone-a { background: var(--zone-a-bg); }
.zone-b { background: var(--zone-b-bg); }
.zone-c { background: var(--zone-c-bg); }

.pass-details {
  display: flex;
  flex-direction: column;
  gap: 8px;
  background: var(--brand-light);
  border-radius: 10px;
  padding: 10px 14px;
  min-width: 148px;
}

.detail-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}

.detail-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.detail-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
}

.pass-footer {
  background: var(--footer-bg);
  padding: 12px 20px 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
}

.barcode {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 32px;
}

.bar {
  width: 2px;
  height: 100%;
  background: var(--bar-color);
  border-radius: 1px;
}

.bar.wide {
  width: 5px;
}

.barcode-num {
  font-size: 10px;
  color: var(--barcode-text);
  font-weight: 600;
  letter-spacing: 0.1em;
}
